import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, AmbientLight, DirectionalLight, Color } from 'three/webgpu';
import { uv, texture, uniform, mix, color, float, time, sin, float as f, PI } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const spec = config.intent?.visualSpec ?? {};
  const palette = spec.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  const group = new Group();

  // ----- Backdrop gradient (dark stage, no flat void) -----
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  backdropMat.colorNode = mix(
    color(palette.surface),
    color(palette.ink),
    smoothstepImpl(uv().y, 0.0, 1.0)
  );
  const backdrop = new Mesh(new PlaneGeometry(7.2, 6.2, 1, 1), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  function smoothstepImpl(a, min, max) {
    const t = a.sub(min).div(max.sub(min));
    return t.clamp(0, 1).mul(t).mul(f(3).sub(t.mul(2)));
  }

  // ----- Main parallax plane (features row card) -----
  const CARD_W = 2.6;
  const CARD_H = 1.6;
  const planeGeo = new PlaneGeometry(CARD_W, CARD_H, 96, 64);

  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.42,
    transparent: false,
  });

  // default colors so we render before textures resolve
  cardMat.colorNode = color(palette.ink);

  const dispAmount = uniform(0.12);
  const uvNode = uv();

  let imageTex = null;
  let depthTex = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    imageTex = tex;
    cardMat.colorNode = texture(tex, uvNode);
    cardMat.needsUpdate = true;
    rebuildDisplacement();
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTex = tex;
    rebuildDisplacement();
  });

  function rebuildDisplacement() {
    if (!depthTex) return;
    const base = texture(depthTex, uvNode).r;
    // subtle time-based parallax breathing (camera-like motion feel)
    const wave = sin(time.mul(0.6).add(uvNode.x.mul(PI))).mul(0.015);
    const t = base.add(wave);
    cardMat.displacementNode = t.mul(dispAmount);
    cardMat.needsUpdate = true;
  }

  const card = new Mesh(planeGeo, cardMat);
  card.position.set(0, 0, 0);
  group.add(card);

  // ----- Divider line + accent edge -----
  const dividerMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.9 });
  dividerMat.colorNode = mix(color(palette.ink), color(palette.paper), float(0.35));
  const divider = new Mesh(new PlaneGeometry(CARD_W, 0.012), dividerMat);
  divider.position.set(0, -0.34, 0.002);

  // Contact shadow under card
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.5, depthWrite: false });
  shadowMat.colorNode = mix(color(palette.surface), color(palette.ink), float(0.2));
  // radial-ish soft strip
  const shadow = new Mesh(new PlaneGeometry(CARD_W * 1.4, 0.5, 1, 1), shadowMat);
  shadow.position.set(0, -0.55, -0.01);
  shadow.scale.set(1, 1, 1);
  group.add(shadow);

  // Accent vertical edge (right side) - emissive red bar
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.0 });
  accentMat.colorNode = color(palette.accent);
  const accentEdge = new Mesh(new PlaneGeometry(0.04, CARD_H, 1, 1), accentMat);
  accentEdge.position.set(CARD_W / 2 + 0.02, 0, 0.004);
  group.add(accentEdge);

  // ----- Lighting (rim/accent added locally) -----
  const ambient = new AmbientLight(new Color(palette.ink), 0.45);
  group.add(ambient);

  const rimAccent = new DirectionalLight(new Color(palette.accent), 0.7);
  rimAccent.position.set(-2.2, 0.6, -1.5);
  group.add(rimAccent);

  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(2.5, 1.5, 2.0);
  group.add(key);

  // ----- Interaction -----
  const baseY = group.position.y;
  const baseX = group.position.x;
  const baseZ = group.position.z;
  let hoverTl = null;
  let clickTl = null;

  const handlers = {
    pointerenter: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' }, 0);
      hoverTl.to(group.rotation, { x: -0.05, duration: 0.5, ease: 'power2.out' }, 0);
      hoverTl.to(accentMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(dispAmount, { value: 0.18, duration: 0.6, ease: 'power2.out' }, 0);
    },
    pointerleave: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: baseY, duration: 0.45, ease: 'power3.out' }, 0);
      hoverTl.to(group.rotation, { x: 0, duration: 0.45, ease: 'power2.out' }, 0);
      hoverTl.to(accentMat, { opacity: 0.0, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(dispAmount, { value: 0.12, duration: 0.5, ease: 'power2.out' }, 0);
    },
    click: () => {
      if (clickTl) clickTl.kill();
      clickTl = gsap.timeline();
      clickTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' }, 0);
      clickTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' }, 0.12);
      clickTl.to(accentMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
      clickTl.to(accentMat, { opacity: 0.5, duration: 0.4, ease: 'power2.out' }, 0.3);
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  group.userData.handlers = handlers;

  // ----- Cleanup -----
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (clickTl) clickTl.kill();
    backdropMat.dispose();
    cardMat.dispose();
    dividerMat.dispose();
    shadowMat.dispose();
    accentMat.dispose();
    planeGeo.dispose();
    backdrop.geometry.dispose();
    divider.geometry.dispose();
    shadow.geometry.dispose();
    accentEdge.geometry.dispose();
  };

  return group;
}
